<?php $u=require_user();$p=q('SELECT * FROM perfiles WHERE usuario_id=?',[$u['id']])->fetch()?:[];$goals=q('SELECT objetivo FROM objetivos_usuarios WHERE usuario_id=?',[$u['id']])->fetchAll(PDO::FETCH_COLUMN);?><div class="container py-5"><div class="row justify-content-center"><div class="col-lg-9"><div class="kicker mb-3">TU ESTILO DE VIDA</div><h1 style="font-size:clamp(2.3rem,5vw,4rem)">Conozcamos tus objetivos.</h1><p class="text-muted mb-4">Esta información orienta la experiencia del prototipo; no representa diagnóstico ni prescripción.</p><form action="actions.php" method="post" class="surface p-4 p-md-5"><input type="hidden" name="action" value="save_quiz"><?=csrf_input()?><h4>01 / Información general</h4><div class="row g-3 mt-1"><div class="col-md-6"><label class="form-label" for="peso">Peso (kg)</label><input class="form-control" id="peso" type="number" step="0.1" min="20" max="350" name="peso_kg" required value="<?=h((string)($p['peso_kg']??''))?>"></div><div class="col-md-6"><label class="form-label" for="altura">Estatura (cm)</label><input class="form-control" id="altura" type="number" min="100" max="250" step="0.1" name="estatura_cm" required value="<?=h((string)($p['estatura_cm']??''))?>"></div><div class="col-md-6"><label class="form-label">Nivel de actividad</label><select class="form-select" name="actividad" required><?php foreach(['baja'=>'Baja','ligera'=>'Ligera','moderada'=>'Moderada','alta'=>'Alta'] as $k=>$v): ?><option value="<?=h($k)?>" <?=($p['actividad']??'')===$k?'selected':''?>><?=h($v)?></option><?php endforeach ?></select></div><div class="col-md-6"><label class="form-label">Días de entrenamiento por semana</label><input class="form-control" type="number" min="0" max="7" name="dias_entrenamiento" required value="<?=h((string)($p['dias_entrenamiento']??'3'))?>"></div><div class="col-12"><label class="form-label">Ejercicio habitual</label><input class="form-control" name="tipo_ejercicio" maxlength="90" placeholder="Ej. caminatas, gimnasio, yoga" value="<?=h((string)($p['tipo_ejercicio']??''))?>"></div></div><hr class="my-4"><h4>02 / ¿Qué te gustaría mejorar?</h4><p class="small-muted">Puedes marcar varios objetivos.</p><div class="row row-cols-1 row-cols-md-3 g-3"><?php foreach(['masa'=>'Masa muscular','rendimiento'=>'Rendimiento físico','energia'=>'Energía','sueno'=>'Sueño','digestion'=>'Digestión','bienestar'=>'Bienestar general'] as $key=>$label): ?><div class="col"><label class="option-card"><input type="checkbox" name="objetivos[]" value="<?=h($key)?>" <?=in_array($key,$goals,true)?'checked':''?>> <strong class="d-inline"><?=h($label)?></strong></label></div><?php endforeach ?></div><hr class="my-4"><h4>03 / Preferencias y restricciones</h4><div class="row g-3 mt-1"><div class="col-md-6"><label class="form-label">Estilo alimentario</label><select class="form-select" name="alimentacion"><?php foreach(['omnivora'=>'Omnívora','vegetariana'=>'Vegetariana','vegana'=>'Vegana','otra'=>'Otra'] as $key=>$label): ?><option value="<?=h($key)?>" <?=($p['alimentacion']??'')===$key?'selected':''?>><?=h($label)?></option><?php endforeach ?></select></div><div class="col-md-6"><label class="form-label">Alergias o restricciones conocidas</label><input class="form-control" name="alergias" placeholder="Ej. leche, soya, nueces" value="<?=h((string)($p['alergias']??''))?>"></div><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" value="1" name="prefiere_organico" id="organic" <?=!empty($p['prefiere_organico'])?'checked':''?>><label class="form-check-label" for="organic">Prefiero ingredientes orgánicos certificados cuando existan.</label></div></div><div class="col-12"><div class="notice-box"><div class="form-check"><input class="form-check-input" type="checkbox" required name="consiente_datos" value="1" id="consent" <?=!empty($p['consiente_datos'])?'checked':''?>><label for="consent" class="form-check-label small">Autorizo expresamente el uso de mis datos de actividad, peso, estatura, objetivos y restricciones para generar sugerencias dentro de este prototipo. Puedo dejar de compartirlos solicitando su eliminación.</label></div></div></div><div class="col-12"><button class="btn btn-brand btn-lg">Guardar y ver recomendaciones →</button></div></div></form></div></div></div>
